// Renders PlantUML through the wasm build of plantuml-core.
// The wasm package is generated by scripts/build-vscode-ext.sh into ./wasm (nodejs target).
'use strict';

const fs = require('node:fs');
const path = require('node:path');
const { log } = require('./log');

const WASM_DIR = path.join(__dirname, '..', 'wasm');
const WASM_GLUE = path.join(WASM_DIR, 'plantuml_wasm.js');
const WASM_BINARY = path.join(WASM_DIR, 'plantuml_wasm_bg.wasm');

let wasm = null;

function wasmStatus() {
  return {
    dir: WASM_DIR,
    glue: fs.existsSync(WASM_GLUE),
    binary: fs.existsSync(WASM_BINARY),
  };
}

function load() {
  if (wasm === null) {
    const status = wasmStatus();
    log(`loading wasm: ${JSON.stringify(status)}`);
    wasm = require(WASM_GLUE);
    log('wasm loaded');
  }
  return wasm;
}

/** Wraps bare statements (`A -> B`) the way a markdown block usually arrives. */
function withBlock(source) {
  return /^[%s]*@start/m.test(source) ? source : `@startuml\n${source}\n@enduml`;
}

/** SVG for a PlantUML source, or an SVG error box when the port rejects it. */
function renderSvg(source) {
  const text = withBlock(source);
  try {
    const svg = load().render(text);
    log(`rendered ${text.length} chars to ${svg.length} chars of svg`);
    return { ok: true, svg };
  } catch (e) {
    const message = String(e && e.message ? e.message : e);
    log(`render failed: ${message}`);
    return { ok: false, svg: errorSvg(message) };
  }
}

function escapeXml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;',
  })[c]);
}

/** The message box the preview shows when a diagram does not render. */
function errorSvg(message) {
  const lines = message.split('\n').slice(0, 4);
  const height = 20 + 16 * lines.length;
  const texts = lines
    .map((l, i) => `<text x="10" y="${20 + 16 * i}" font-family="sans-serif" font-size="12" fill="#b31d28">${escapeXml(l)}</text>`)
    .join('');
  return `<svg xmlns="http://www.w3.org/2000/svg" width="480" height="${height}">` +
    `<rect width="100%" height="100%" fill="#fff5f5" stroke="#b31d28"/>${texts}</svg>`;
}

module.exports = { renderSvg, errorSvg, wasmStatus, WASM_DIR };
